import {createClient} from 'https://esm.sh/@supabase/supabase-js@2.95.3';
export const db=createClient('https://typbkzwbrmkrfkfxjrgi.supabase.co','sb_publishable_Oto-5IRPHgWceHq_uzrsiw_JBBZbAOT',{auth:{storageKey:'taktooka-captain-portal',detectSessionInUrl:false}});
export const $=id=>document.getElementById(id);
export async function rpc(name,action,data={}){const r=await db.rpc(name,{p_action:action,p_data:data});if(r.error)throw r.error;return r.data;}
export async function invoke(name,body){const r=await db.functions.invoke(name,{body});if(r.error){let detail;try{detail=await r.error.context?.json();}catch{}throw new Error(detail?.error||'CONNECTION_ERROR');}if(r.data?.error)throw new Error(r.data.error);return r.data;}
const errors={ACCOUNT_EXISTS:'هذا الرقم مسجّل؛ اختار «عندي حساب».',WRONG_PASSWORD:'كلمة السر غير صحيحة.',LOGIN_LOCKED:'محاولات الدخول متوقفة؛ تواصل ويا الإدارة.',ACCOUNT_BLOCKED:'هذا الحساب موقوف؛ تواصل ويا الإدارة.',RATE_LIMIT:'محاولات كثيرة؛ انتظر قليلًا وحاول مرة ثانية.',FULL_NAME_REQUIRED:'اكتب اسمك الثلاثي كاملًا.',AREA_REQUIRED:'اختر المحافظة واكتب المنطقة.',DOCUMENTS_REQUIRED:'أضف صورتي الوجه الأمامي والخلفي للجنسية.',APPLICATION_LOCKED:'طلبك قيد المراجعة؛ لا يمكن تعديله حاليًا.',LINK_EXPIRED:'الرابط منتهي أو مستخدم؛ اطلب رابط جديد من الإدارة.',INVALID_PASSWORD:'كلمة السر لازم تكون من 8 إلى 128 حرفًا.',INVALID_PHONE:'اكتب رقم عراقي صحيح يبدأ 07 ويتكون من 11 رقم.',REGISTER_UNAVAILABLE:'تعذر إنشاء الحساب؛ جرّب تسجيل الدخول أو تواصل ويا الإدارة.',PRIVACY_CONSENT_REQUIRED:'وافق على سياسة الخصوصية أولًا.'};
export function notice(value,error=false){$('message').textContent=value;$('message').dataset.error=String(error);}
export async function run(fn){if(document.body.dataset.busy)return;document.body.dataset.busy='true';const buttons=[...document.querySelectorAll('button')].filter(b=>!b.disabled);buttons.forEach(b=>b.disabled=true);try{await fn();}catch(e){const message=Object.entries(errors).find(([key])=>String(e.message).includes(key))?.[1];notice(message||e.userMessage||'تعذرت العملية؛ تحقق من الاتصال وحاول مرة ثانية.',true);}finally{delete document.body.dataset.busy;buttons.forEach(b=>b.disabled=false);}}
export function problem(text){throw Object.assign(new Error(text),{userMessage:text});}
export const localPhone=v=>String(v||'').replace(/^\+964/,'0');
export function eye(input,button){button.onclick=()=>{input.type=input.type==='password'?'text':'password';button.textContent=input.type==='text'?'إخفاء':'إظهار';button.setAttribute('aria-pressed',String(input.type==='text'));};}
